@TransactionalEventListener(phase = TransactionPhase.AFTER_COMMIT)
public void onOrderCreated(OrderCreatedEvent event) {
    // Внимание: родительское JDBC-соединение уже зафиксировано и закрыто!
    deliveryRepository.save(new DeliveryStatus(event.getOrderId(), "DISPATCHED"));
}

public void payOrder(Order order) {
    orderRepository.save(order);
    try {
        loyaltyService.deductPoints(order.getUserId(), order.getPoints());
    } catch (BonusException e) {
        log.warn("Списание бонусов не удалось, продолжаем за полную сумму");
    }
    cardPaymentService.chargeCard(order.getId(), order.getTotal());
}

public void deductPoints(Long userId, BigDecimal points) {
    userAccountRepository.deductBonus(userId, points);
}

@Async
public CompletableFuture<Report> generateFiscalReport(Long reportId) {
    Report report = reportRepository.findById(reportId).orElseThrow();
    // Логика расчета
    return CompletableFuture.completedFuture(report);
}

public void auditReconciliation(Long accountId) {
    BigDecimal sum = ledgerRepository.calculateSum(accountId);
    auditRepository.verifySum(accountId, sum);
}

